-- ============================================================
-- SES/platform -- DEV-ONLY seed: APP_USER rows from CARSIS export
-- Run against the platform schema after platform/sql/01_ddl.sql +
-- platform/sql/02_seed_data.sql have created APP_USER.
--
-- WARNING: DEV/LOCAL USE ONLY. Source data is extracted-carsis-user.sql
-- (CARSIS.APP_USER export, generated 21-AUG-2026). Pre-existing
-- non-LDAP rows (ADMIN, 111111, 123456 -- IS_LDAP=0 admin/test/dummy
-- accounts) from the source export are dropped here. Every remaining
-- row was LDAP in the source (IS_LDAP=1); auth_type is forced to
-- LOCAL and password forced to a bcrypt hash of "test" so every
-- seeded account is usable without a real LDAP bind in dev.
-- Real employee names/emails still carried through -- never run this
-- against a shared or production schema.
--
-- Column mapping (CARSIS.APP_USER -> APP_USER):
--   USER_ID/EMP_ID (badge) -> username, NAME -> full_name,
--   EMAIL -> email, CREATE_DATE -> created_date, UPDATE_DATE ->
--   updated_date (falls back to CREATE_DATE when the source value is
--   NULL, so every row keeps a timestamp). user_id is NOT the source
--   USER_ID/badge -- it's a fixed incremental UUID (same convention
--   as platform/sql/02_seed_data.sql's
--   '00000000-0000-0000-0000-000000000001'/'...002' admin/sysadm
--   rows), starting at '...003' so it never collides with those two,
--   assigned in full_name alphabetical order. ROLE_ID, PWD, IS_ACTIVE
--   (always 1 in source), IS_LDAP, LDAP_USER, IS_ALLOW_LOGINAS,
--   CREATE_BY, UPDATE_BY, FILTER, FILTER_VALUE, INCLUDE_DESCENDANT,
--   FILTER_PTB and EMP_ID_ZP have no target column and are dropped.
--   password and auth_type are NOT carried through -- see above.
--   active_flag defaults to 'Y'; created_by/updated_by set to
--   'DEV_SEED' (no equivalent source column).
-- ============================================================

SET DEFINE OFF;


COMMIT;


-- ============================================================
-- REVERT HELPER -- run manually when done testing with LOCAL auth.
-- Restores every row this script seeded (created_by='DEV_SEED') back
-- to auth_type='LDAP' and clears the test password hash, so login
-- goes through LDAP bind again. Not run automatically -- uncomment
-- and execute by hand.
-- ============================================================
/*
CREATE OR REPLACE PROCEDURE revert_dev_seed_app_user_to_ldap AS
BEGIN
    UPDATE app_user
       SET auth_type    = 'LDAP',
           password      = NULL,
           updated_by    = 'DEV_SEED',
           updated_date  = SYSDATE
     WHERE created_by = 'DEV_SEED'
       AND auth_type  = 'LOCAL';
    COMMIT;
END revert_dev_seed_app_user_to_ldap;
/

-- BEGIN
--     revert_dev_seed_app_user_to_ldap;
-- END;
-- /

-- DROP PROCEDURE revert_dev_seed_app_user_to_ldap;
*/

